def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'C'
    if n == 2:
        return 'D' if history[0][1] == 'D' and history[1][1] == 'D' else 'C'

    last_me, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    for me, op in history:
        if op == 'D':
            opp_d += 1
        if me == 'D':
            my_d += 1

    window = min(10, n)
    start = n - window
    recent_opp_d = 0
    recent_opp_c = 0
    recent_my_d = 0
    for i in range(start, n):
        me, op = history[i]
        if op == 'D':
            recent_opp_d += 1
        else:
            recent_opp_c += 1
        if me == 'D':
            recent_my_d += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    resp_forg = 0
    resp_pun = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                resp_forg += 1
            else:
                resp_pun += 1

    very_coop = opp_d * 10 <= n
    coop = opp_d * 4 <= n
    moderate = opp_d * 3 <= n
    heavy = (opp_d * 2 > n) or (recent_opp_d * 4 >= window * 3)

    forgiving_once = (
        resp_forg >= 1 and
        resp_pun == 0 and
        opp_d <= 2 and
        my_d <= 2 and
        recent_opp_c >= recent_opp_d
    )
    forgiving_many = (
        resp_forg >= 2 and
        resp_forg >= resp_pun and
        opp_d * 3 <= n
    )
    soft = forgiving_once or forgiving_many
    hard = (
        resp_pun >= 2 and resp_pun > resp_forg
    ) or (
        resp_pun >= 1 and resp_pun > resp_forg and coop
    )

    if last_opp == 'C':
        if soft and recent_opp_d <= 2 and recent_my_d <= 5:
            return 'D'
        if hard and coop:
            return 'C'
        return 'C'

    if last_me == 'D':
        if heavy and opp_d * 3 > n:
            return 'D'
        if recent_opp_c >= recent_opp_d or opp_d * 2 <= n or very_coop:
            return 'C'
        return 'D'

    if opp_streak >= 2 or recent_opp_d * 2 > window:
        return 'D'

    if n < 10 and opp_d <= 1:
        return 'C'

    if heavy:
        return 'D'

    if soft:
        return 'D'

    if hard and coop:
        return 'C'

    if very_coop and my_d <= 2:
        return 'C'

    if coop and my_d <= max(1, n // 5):
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    if moderate and rng.random() < 0.2:
        return 'C'

    return 'D'
